const listKillsForFight = `-- name: ListKillsForFight :many
SELECT k.killmail_id, k.killmail_time, k.system_id, k.victim_character_id,
       k.ship_type_id, k.damage_taken, k.value_ours,
       COALESCE((SELECT a.damage_done FROM kill_attackers a
                 WHERE a.killmail_id = k.killmail_id AND a.character_id = $1
                 LIMIT 1), 0)::bigint AS my_damage
FROM kills k
WHERE k.killmail_time BETWEEN $2 AND $3
  AND (k.victim_character_id = $1
       OR k.killmail_id IN (SELECT a.killmail_id FROM kill_attackers a
                           WHERE a.character_id = $1 AND a.character_id > 0))
ORDER BY k.killmail_time, k.killmail_id
LIMIT 200
`

type ListKillsForFightParams struct {
	CharacterID int64     `json:"character_id"`
	FromAt      time.Time `json:"from_at"`
	ToAt        time.Time `json:"to_at"`
}

type ListKillsForFightRow struct {
	KillmailID        int64           `json:"killmail_id"`
	KillmailTime      time.Time       `json:"killmail_time"`
	SystemID          int64           `json:"system_id"`
	VictimCharacterID int64           `json:"victim_character_id"`
	ShipTypeID        int64           `json:"ship_type_id"`
	DamageTaken       int64           `json:"damage_taken"`
	ValueOurs         sql.NullFloat64 `json:"value_ours"`
	MyDamage          int64           `json:"my_damage"`
}

// The mails a character is on, as victim or attacker, in a window,
// with the character's own damage on each.
func (q *Queries) ListKillsForFight(ctx context.Context, arg ListKillsForFightParams) ([]ListKillsForFightRow, error) {
	rows, err := q.db.Query(ctx, listKillsForFight, arg.CharacterID, arg.FromAt, arg.ToAt)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListKillsForFightRow
	for rows.Next() {
		var i ListKillsForFightRow
		if err := rows.Scan(
			&i.KillmailID,
			&i.KillmailTime,
			&i.SystemID,
			&i.VictimCharacterID,
			&i.ShipTypeID,
			&i.DamageTaken,
			&i.ValueOurs,
			&i.MyDamage,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

